--   Sigma Computing — Дизайн та креатив / Аналіз даних
--   Count — Дизайн та креатив / Аналіз даних
--   Klipfolio — Дизайн та креатив / Звіти
--   Whatagraph — Дизайн та креатив / Звіти
--   Supermetrics — Дизайн та креатив / Звіти
--   Zoho Analytics — Дизайн та креатив / Звіти
--   Geckoboard — Дизайн та креатив / Звіти
--   Grow (Grow Data Platform) — Дизайн та креатив / Звіти
--   ReportGarden — Дизайн та креатив / Звіти
--
-- Застосування (phpMyAdmin хостингу, БД gu621051_ailabhublive): вкладка SQL (або Імпорт) → цей файл → Вперёд.
-- БЕЗ ФІКСОВАНИХ id: продукт додається, лише якщо продукту з таким самим нормалізованим URL ще немає;
-- його id береться через @pid, категорії/підкатегорії — за slug. Тарифи — лише для щойно доданого продукту.
-- Безпечно повторювати; жодних DROP / DELETE / перестворення таблиць. created_by не переноситься (NULL).
-- Автопереклади (product_translations, pricing_plan_translations; усі source = auto) не переносяться —
-- сайт згенерує їх заново при першому показі англійською.
-- =====================================================================

-- Tableau
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'tableau.com' ORDER BY `id` LIMIT 1);

