INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Tableau', NULL, 'https://tableau.com', NULL, NULL, 'Один із найвідоміших інструментів візуалізації даних — перетворює складні таблиці на наочні, інтерактивні дашборди методом перетягування елементів.', NULL, 'Tableau дозволяє підключитись до практично будь-якого джерела даних (бази даних, таблиці, хмарні сховища) і побудувати наочні інтерактивні дашборди без написання коду, методом перетягування елементів. Вважається золотим стандартом якості візуалізації даних у галузі, з дуже гнучким контролем над дизайном графіків. Тепер частина Salesforce, з AI-функціями Tableau Pulse для розмовної аналітики.', NULL, 'Побудова інтерактивних дашбордів без коду\nПідключення до практично будь-якого джерела даних\nГнучкий контроль над дизайном візуалізацій\nAI-розмовна аналітика (Tableau Pulse)', NULL, 'Аналітики даних, команди звітності, компанії, що потребують якісної візуалізації складних даних', NULL, 'web,desktop', 'course', 'published', '0', 'found', '2026-09-05 06:57:02' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'tableau.com');
