INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Microsoft Power BI', NULL, 'https://powerbi.microsoft.com', NULL, NULL, 'Один із найпопулярніших і найдоступніших інструментів бізнес-аналітики — глибока інтеграція з Microsoft 365 і вбудований AI-помічник Copilot.', NULL, 'Power BI перетворює дані з таблиць, баз даних і хмарних сервісів на інтерактивні звіти й дашборди. Особливо вигідний для компаній, що вже користуються Microsoft 365 — глибоко інтегрується з Excel, Teams і SharePoint. Вбудований Copilot дозволяє ставити запитання про дані звичайною мовою й отримувати готові візуалізації у відповідь.', NULL, 'Побудова інтерактивних звітів і дашбордів\nГлибока інтеграція з Excel, Teams, SharePoint\nAI-помічник Copilot для запитів звичайною мовою\nАвтоматичне оновлення даних за розкладом', NULL, 'Компанії будь-якого розміру, особливо ті, що вже користуються Microsoft 365', NULL, 'web,mobile,desktop', 'course', 'published', '0', 'found', '2026-09-05 06:57:02' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'powerbi.microsoft.com');
