INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Google Looker Studio', NULL, 'https://lookerstudio.google.com', NULL, NULL, 'Повністю безкоштовний інструмент візуалізації даних від Google — особливо зручний для тих, хто вже користується Google Analytics, Ads чи Sheets.', NULL, 'Google Looker Studio дозволяє перетворити дані з Google Analytics, Google Ads, Google Sheets, BigQuery та понад 800 інших джерел на наочні звіти й дашборди без коду. Базовий функціонал повністю безкоштовний і достатній для більшості малих команд і маркетологів. Особливо популярний вибір для тих, хто вже працює в екосистемі Google.', NULL, 'Підключення до Google Analytics, Ads, Sheets, BigQuery та 800+ інших джерел\nПобудова звітів і дашбордів без коду\nСпільний доступ і співавторство в реальному часі\nГотові шаблони звітів', NULL, 'Маркетологи, малі команди, будь-хто, хто вже працює з продуктами Google', NULL, 'web', 'basic', 'published', '0', 'no_partnership', '2026-09-05 06:57:02' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'lookerstudio.google.com');
