INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Pro', NULL, '9.00', 'month', 'розширена співпраця й адміністрування (за проєкт)', NULL FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Metabase', NULL, 'https://metabase.com', NULL, NULL, 'Безкоштовний відкритий інструмент для аналізу даних — дозволяє ставити запитання про дані звичайною мовою без знання SQL.', NULL, 'Metabase — відкритий інструмент бізнес-аналітики, що дозволяє неспеціалістам ставити запитання про дані звичайною мовою (наприклад \"скільки продажів було минулого місяця\") і отримувати готові графіки у відповідь, без потреби писати SQL-запити. Можна встановити на власний сервер безкоштовно, або скористатись хмарною версією.', NULL, 'Запитання про дані звичайною мовою без SQL\nПобудова дашбордів і графіків\nМожливість самостійного розміщення на власному сервері\nАвтоматичні сповіщення при зміні показників', NULL, 'Невеликі команди й компанії, що хочуть безкоштовну або недорогу альтернативу великим BI-платформам', NULL, 'web', 'basic', 'published', '0', 'no_partnership', '2026-09-05 06:57:02' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'metabase.com');
