INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Microsoft Excel', NULL, 'https://microsoft.com/microsoft-365/excel', NULL, NULL, 'Найпоширеніша у світі програма для роботи з таблицями й аналізу даних, тепер із вбудованим AI-помічником Copilot для формул і аналізу.', NULL, 'Microsoft Excel залишається найпоширенішим у світі інструментом для роботи з таблицями даних — розрахунки, зведені таблиці, графіки. AI-помічник Copilot всередині Excel допомагає писати складні формули звичайною мовою, автоматично аналізує дані й пропонує інсайти, яких людина могла не помітити. Базові навички Excel вважаються необхідним мінімумом у більшості офісних професій.', NULL, 'Розрахунки й формули для роботи з таблицями даних\nAI-помічник Copilot для формул звичайною мовою\nЗведені таблиці та графіки\nАвтоматичний аналіз даних з пропозицією інсайтів', NULL, 'Практично будь-яка професія, що працює з таблицями даних — від фінансів до маркетингу', NULL, 'web,mobile,desktop', 'basic', 'published', '0', 'found', '2026-09-05 06:57:02' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'microsoft.com/microsoft-365/excel');
