INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Coolors', NULL, 'https://coolors.co', NULL, NULL, 'Наддшвидкий генератор кольорових палітр — нова палітра за пробіл, понад 10 млн готових схем. Безкоштовно з обмеженнями, Pro — $3/міс.', NULL, 'Coolors дозволяє миттєво генерувати палітри клавішею пробіл, витягувати кольори із зображень, перевіряти контраст доступності та переглядати палітру на макетах.', NULL, 'Миттєва генерація палітри клавішею пробіл\nВитягування кольорів із завантажених зображень\nПеревірка контрасту для доступності\nAI Color Bot для розширеної генерації (Pro)', NULL, 'Дизайнери й розробники, яким потрібна швидка кольорова інспірація', NULL, 'web,mobile', 'none', 'published', '0', 'found', '2026-09-15 18:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'coolors.co');
