INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Huemint', NULL, 'https://huemint.com', NULL, NULL, 'AI-генератор кольорових палітр на основі машинного навчання — одразу показує палітру на прикладах брендингу й дизайну. Повністю безкоштовний.', NULL, 'Huemint використовує ML-модель, щоб одразу застосовувати згенеровані кольори до зразків ілюстрацій, логотипів і макетів. Сильна сторона — генерація цілісних брендових кольорових систем.', NULL, 'Генерація палітр із застосуванням на прикладах дизайну\nФокус на брендових кольорових системах\nКонтроль контрасту між кольорами\nБез реєстрації й оплати', NULL, 'Дизайнери, що одразу хочуть бачити палітру в контексті реального макета', NULL, 'web', 'none', 'published', '0', 'no_partnership', '2026-09-15 18:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'huemint.com');
