INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Безкоштовний', NULL, '0.00', 'free', 'повний доступ без реєстрації й оплати', NULL FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Colormind', NULL, 'http://colormind.io', NULL, NULL, 'AI-генератор палітр на основі глибокого навчання (GAN), тренований на палітрах з Adobe Color й Dribbble. Повністю безкоштовний.', NULL, 'Colormind щодня підвантажує нові датасети реальних палітр із фотографій, фільмів та мистецтва, а нейромережа-класифікатор оцінює естетичну привабливість результату. Є REST API.', NULL, 'Генерація палітр через GAN, треновану на реальних джерелах\nЩоденне оновлення датасетів для нової інспірації\nМожливість \"заблокувати\" окремі кольори при генерації\nБезкоштовний REST API для особистого використання', NULL, 'Дизайнери й розробники, що хочуть API для генерації палітр', NULL, 'web', 'none', 'published', '0', 'no_partnership', '2026-09-15 18:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'colormind.io');
