INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Muzli AI Colors', NULL, 'https://colors.muz.li', NULL, NULL, 'AI-генератор палітр від екосистеми Muzli — палітри за ключовим словом, настроєм чи базовим кольором з експортом у Figma/CSS/Tailwind. Повністю безкоштовний.', NULL, 'Muzli Colors дає доступ до тисяч трендових кольорових комбінацій, зібраних із реальних креативних проєктів, і генерує палітри за ключовим словом, настроєм, базовим кольором чи референсом.', NULL, 'Генерація палітр за ключовим словом чи настроєм\nТисячі трендових палітр зі спільноти\nЕкспорт у Figma, CSS, Tailwind\nПошук за базовим кольором чи референсом', NULL, 'Дизайнери, яким потрібні готові до впровадження палітри', NULL, 'web', 'none', 'published', '0', 'no_partnership', '2026-09-15 18:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'colors.muz.li');
