INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'ColorMagic', NULL, 'https://colormagic.app', NULL, NULL, 'AI-генератор палітр на основі GPT — опиши настрій чи завантаж фото, отримай готову палітру. Безкоштовний план, Pro — $6/міс.', NULL, 'ColorMagic перетворює текстовий опис настрою або завантажене зображення на готову кольорову палітру за допомогою GPT-моделі. Дозволяє коригувати насиченість і яскравість, копіювати коди в HEX/RGB/HSL.', NULL, 'Генерація палітри за текстовим описом настрою (GPT)\nВитягування палітри із завантаженого фото\nКоригування насиченості, яскравості й відтінку\nБезкоштовний публічний API', NULL, 'Дизайнери й розробники, що хочуть палітру за словесним описом', NULL, 'web', 'none', 'published', '0', 'no_partnership', '2026-09-15 18:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'colormagic.app');
