INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Adobe Color', NULL, 'https://color.adobe.com', NULL, NULL, 'Безкоштовний інструмент Adobe для створення й дослідження кольорових палітр за правилами гармонії кольору. Глибша інтеграція — через підписку Creative Cloud.', NULL, 'Adobe Color дозволяє створювати палітри на кольоровому колесі за класичними правилами гармонії, витягувати кольори із зображень і досліджувати тренди спільноти.', NULL, 'Кольорове колесо з правилами гармонії\nВитягування палітри із зображення\nСпільнота й трендові палітри користувачів\nПряма інтеграція з Photoshop, Illustrator', NULL, 'Дизайнери в екосистемі Adobe, що добирають кольори для проєктів', NULL, 'web,mobile', 'none', 'published', '0', 'found', '2026-09-15 18:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'color.adobe.com');
