INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'ColorKit', NULL, 'https://colorkit.co', NULL, NULL, 'Безкоштовна колекція інструментів для роботи з кольором — генератори палітр, градієнтів і конвертери кольорових кодів.', NULL, 'ColorKit — набір безкоштовних веб-утиліт для дизайнерів: генератори кольорових палітр і градієнтів, конвертер кодів, перевірка контрасту та бібліотека готових палітр для натхнення.', NULL, 'Генератор кольорових палітр і градієнтів\nКонвертер кольорових кодів HEX/RGB/HSL\nПеревірка контрасту доступності\nБібліотека готових палітр', NULL, 'Дизайнери й розробники, яким потрібен швидкий набір кольорових утиліт', NULL, 'web', 'none', 'published', '0', 'no_partnership', '2026-09-15 18:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'colorkit.co');
