INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'v0', NULL, 'https://v0.app', NULL, NULL, 'AI-інструмент від Vercel для генерації коду та UI з опису — Design Mode для візуального редагування, деплой одразу на Vercel. Безкоштовний старт, Plus — $30/міс.', NULL, 'v0 генерує робочий UI-код із текстового промпту чи макета, дозволяє візуально редагувати результат у Design Mode, синхронізується з GitHub і деплоїться напряму на Vercel.', NULL, 'Генерація UI-коду з текстового опису\nDesign Mode — візуальне редагування згенерованого\nСинхронізація з GitHub, деплой на Vercel\nДоступ до кількох AI-моделей (за тарифом)', NULL, 'Розробники й дизайнери, що швидко переходять від ідеї до робочого UI', NULL, 'web,mobile', 'basic', 'published', '0', 'no_partnership', '2026-09-15 19:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'v0.app');
