INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Builder.io', NULL, 'https://www.builder.io', NULL, NULL, 'AI-платформа для генерації коду й контенту — візуальний IDE з підтримкою дизайн-систем. Безкоштовно, Pro від $24/користувача/міс.', NULL, 'Builder.io поєднує візуальний IDE для генерації коду з AI-контрольованою CMS, підтримує інтеграції з GitHub/GitLab/Bitbucket, плагін для Figma й розширення для VS Code.', NULL, 'Візуальний IDE для генерації коду з урахуванням дизайн-системи\nAI-контрольована візуальна CMS\nПлагін Figma та розширення VS Code\nСпільна робота в реальному часі', NULL, 'Команди розробки й маркетингу, що прискорюють вихід продукту через AI', NULL, 'web', 'basic', 'published', '0', 'found', '2026-09-15 19:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'builder.io');
