INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Anima', NULL, 'https://www.animaapp.com', NULL, NULL, 'Платформа перетворення дизайну на код — з Figma, скріншотів сайтів чи AI-промпту в HTML/React/Vue. Безкоштовний старт, Enterprise від $500/міс.', NULL, 'Anima конвертує Figma-дизайни, живі сайти чи зображення на робочий код, з AI-агентом Buddy для допомоги в Figma та MCP-інтеграцією з Claude.', NULL, 'Figma в код (HTML, React, Vue)\nКлонування живих сайтів у редагований код\nAI-агент Buddy — копілот дизайну у Figma\nMCP-інтеграція з Claude та іншими AI-інструментами', NULL, 'Дизайнери й розробники, що перетворюють макети на робочий код', NULL, 'web,desktop', 'basic', 'published', '0', 'no_partnership', '2026-09-15 19:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'animaapp.com');
