INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Locofy', NULL, 'https://www.locofy.ai', NULL, NULL, 'AI-платформа \"Design to Code\" — перетворює макети на робочий фронтенд-код.', NULL, 'Locofy автоматизує перехід від дизайну до коду через AI, конвертуючи макети у фронтенд-код для швидшої розробки.', NULL, 'AI-конвертація дизайну в код\nDesign-to-code робочий процес\nЕкспорт у популярні фронтенд-фреймворки\nІнтеграція з Figma', NULL, 'Розробники й дизайнери, що автоматизують перехід від макета до коду', NULL, 'web', 'basic', 'published', '0', 'no_partnership', '2026-09-15 19:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'locofy.ai');
