INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'TeleportHQ', NULL, 'https://teleporthq.io', NULL, NULL, 'Візуальний конструктор сайтів, застосунків і онлайн-магазинів з AI-асистентом і експортом коду. 7-денний трайл, Pro від $14/міс.', NULL, 'TeleportHQ дає AI-асистента прямо в редакторі для побудови сайтів і застосунків, з експортом коду в React, Next.js, Vue, Angular чи HTML/CSS, вбудованою CMS, блогом та e-commerce функціями.', NULL, 'AI-асистент для побудови сайтів і застосунків\nЕкспорт коду в React, Next.js, Vue, Angular\nВбудована CMS, блог, e-commerce\nПлагін Figma-в-код, аналітика й хостинг у комплекті', NULL, 'Дизайнери й розробники, що будують сайти й застосунки з експортом у код', NULL, 'web', 'basic', 'published', '0', 'no_partnership', '2026-09-15 19:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'teleporthq.io');
