INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Polymer', NULL, 'https://polymersearch.com', NULL, NULL, 'Платформа візуалізації даних і дашбордів без коду — підключи дані, отримай AI-інсайти. Базовий тариф від $10/міс.', NULL, 'Polymer будує інтерактивні дашборди й звіти з Shopify, Google Sheets, Google Analytics, Facebook/Google Ads та інших джерел, а розмовний AI відповідає на запитання про дані візуально.', NULL, 'Автогенерація дашбордів і виявлення прихованих інсайтів\nРозмовний AI-запит до даних природною мовою\nВбудована аналітика для зовнішніх застосунків\nІнтеграції з Shopify, Google Ads, Salesforce, CSV/XLS', NULL, 'Аналітики, власники ecommerce, маркетингові команди й агенції', NULL, 'web', 'none', 'published', '0', 'no_partnership', '2026-09-15 21:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'polymersearch.com');
