INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Hex', NULL, 'https://hex.tech', NULL, NULL, 'Аналітична платформа з агентними ноутбуками й AI-чатами для дослідження даних. Community — безкоштовно, Professional від $36/редактора/міс.', NULL, 'Hex поєднує ноутбуки з AI-агентами для аналізу даних, розмовну аналітику (Threads) для самостійного дослідження та публікацію інтерактивних дата-застосунків.', NULL, 'Агентні ноутбуки з AI для аналізу даних\nThreads — розмовна аналітика для самообслуговування\nПублікація інтерактивних дата-застосунків\nSSO, аудит-логи, сертифікації відповідності', NULL, 'Дата-аналітики, команди й підприємства, що будують спільну аналітику', NULL, 'web', 'basic', 'published', '0', 'no_partnership', '2026-09-15 21:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'hex.tech');
