INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Deepnote', NULL, 'https://deepnote.com', NULL, NULL, 'Спільні хмарні ноутбуки для аналізу даних з AI-автодоповненням коду (Python/SQL). Безкоштовно назавжди, Team від $39/редактора/міс.', NULL, 'Deepnote дає командам спільно писати й виконувати код для аналітики та ML у реальному часі, з AI-генерацією коду, інтерактивними дата-застосунками та підтримкою ETL-пайплайнів.', NULL, 'Спільні ноутбуки в реальному часі (Python, SQL)\nDeepnote AI — автодоповнення й генерація коду\nІнтерактивні дата-застосунки й дашборди\nІнтеграції зі Snowflake, BigQuery, Databricks', NULL, 'Дата-аналітики, науковці й інженерні команди', NULL, 'web', 'basic', 'published', '0', 'no_partnership', '2026-09-15 21:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'deepnote.com');
