INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Rows', NULL, 'https://rows.com', NULL, NULL, 'AI-таблиця для команд — витягує дані з PDF, імпортує бізнес-дані й аналізує їх через AI. Безкоштовний план, Plus від $8/користувача/міс.', NULL, 'Rows поєднує звичну таблицю з AI-аналітиком, що обробляє PDF та зображення, збагачує клітинки даними напряму з хмарних сервісів і дозволяє будувати кастомні воркфлоу через API.', NULL, 'AI-аналітик для запитів до даних\nAI Vision — витяг даних з PDF і зображень\nАвтоматизація імпорту з хмарних сервісів\nAPI для кастомних воркфлоу', NULL, 'Команди, що обробляють бізнес-дані в масштабі', NULL, 'web', 'none', 'published', '0', 'no_partnership', '2026-09-15 21:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'rows.com');
