INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Better Analyst', NULL, 'https://betteranalyst.com', NULL, NULL, 'Універсальна AI-платформа аналітики — підключення даних, дашборди, автоматизовані звіти в одному робочому просторі (колишній Formula Bot). Starter від $10/міс.', NULL, 'Better Analyst обʼєднує візуалізацію, трансформацію й автоматизацію даних, генерує дашборди за шаблонами й автоматизовані пайплайни звітності з понад 30 конекторами.', NULL, 'AI-дашборди за шаблонами з кастомізацією\nАвтоматизовані та заплановані потоки даних\nТекстовий аналіз: тональність, переклад, ключові слова\nПонад 30 конекторів даних і вбудована аналітика через iframe', NULL, 'Соло-аналітики, малий бізнес і команди, що автоматизують звітність', NULL, 'web', 'none', 'published', '0', 'no_partnership', '2026-09-15 21:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'betteranalyst.com');
