INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Sigma Computing', NULL, 'https://www.sigmacomputing.com', NULL, NULL, 'BI-платформа з AI-застосунками й агентами для роботи з даними в реальному часі напряму в сховищі даних. Ціна за запитом.', NULL, 'Sigma поєднує BI з AI-інструментарієм і агентами, що діють автономно на живих даних, зі спредшит-інтерфейсом для запису назад у джерело.', NULL, 'AI-застосунки, що працюють на живих даних\nАвтономні AI-агенти для дій над даними\nСпредшит-інтерфейс з можливістю запису в джерело\nВбудована аналітика (white-label)', NULL, 'Фінанси, продажі, supply chain команди у фінтех, охороні здоровʼя, рітейлі', NULL, 'web', 'basic', 'published', '0', 'found', '2026-09-15 21:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'sigmacomputing.com');
