INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'Grow (Grow Data Platform)', NULL, 'https://www.growdataplatform.ai', NULL, NULL, 'No-code BI-платформа з 150+ конекторами даних для автоматизованої звітності без SQL. Тарифи за запитом.', NULL, 'Grow дає non-технічним користувачам самостійно будувати ETL-конвеєри, дашборди й KPI-звіти без знання SQL, з підключенням до BigQuery, HubSpot, Salesforce та інших джерел.', NULL, '150+ готових конекторів даних\nNo-code ETL та підготовка даних\nІнтерактивні дашборди й KPI-візуалізація\nНеобмежена кількість користувачів з контролем доступу', NULL, 'Нетехнічні команди, що хочуть самостійно будувати BI-звіти', NULL, 'web', 'none', 'published', '0', 'no_partnership', '2026-09-15 21:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'growdataplatform.ai');
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE c.`slug` = 'design-creative';
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'design-creative' AND s.`slug` = 'reports';
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Тарифи не розкриті публічно', NULL, '0.00', 'free', 'лише запит безкоштовного тріалу', NULL FROM DUAL WHERE @new = 1;
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`) SELECT 'ReportGarden', NULL, 'https://www.reportgarden.com', NULL, NULL, 'Платформа автоматизованих маркетингових звітів (SMM, SEO, платна реклама) для агенцій. Від $75/міс.', NULL, 'ReportGarden автоматизує генерацію звітів із соцмереж, SEO та платної реклами, обʼєднуючи дані з 100+ джерел у кастомізовані звіти для клієнтів агенції.', NULL, 'Автоматизовані звіти SMM, SEO, платної реклами\nОбʼєднання даних зі 100+ джерел\nКастомні метрики й шаблони звітів\n14-денний пробний період без картки', NULL, 'Маркетингові агенції, що звітують перед клієнтами', NULL, 'web', 'basic', 'published', '0', 'found', '2026-09-15 21:00:00' FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'reportgarden.com');
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE c.`slug` = 'design-creative';
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE c.`slug` = 'design-creative' AND s.`slug` = 'reports';
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Standard', NULL, '75.00', 'month', 'до 5 клієнтів, необмежені звіти', NULL FROM DUAL WHERE @new = 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Professional', NULL, '125.00', 'month', 'до 10 клієнтів, преміум-шаблони', NULL FROM DUAL WHERE @new = 1;
